(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0008.js"] = [{"id":"glyph-kai-7434","script":"kai","character":"琴","reading":"qín","description":"qín：(1)古代弦乐器，最初是五根弦，后加至七根弦（亦称七弦琴”；通称古琴”）～瑟。～曲。～师。～意。抚～。～棋书画。\n(2)某些乐器的统称钢～。月～→～。口～。竖～。小提～。～书（曲艺的一种）。弹（tán）～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琴"},{"id":"glyph-kai-743c","script":"kai","character":"琼","reading":"qióng","description":"博具,相当于后来的骰子\n比喻雪\n⒈美玉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琼"},{"id":"glyph-kai-7459","script":"kai","character":"瑙","reading":"nǎo","description":"nǎo：〔玛～〕见玛”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑙"},{"id":"glyph-kai-745e","script":"kai","character":"瑞","reading":"ruì","description":"ruì：(1)古代作为凭信的玉器～玉（诸侯朝见帝王时所执玉器的统称）。～节。～符。\n(2)吉详，好预兆～气。～芝。～签。～雨。祥～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑞"},{"id":"glyph-kai-745f","script":"kai","character":"瑟","reading":"sè","description":"sè：(1)弦乐器，似琴。长近三米，古有五十根弦，后为二十五根或十六根弦，平放演奏鼓～。\n(2)矜持端庄的样子。\n(3)洁净鲜明的样子。\n〔～～〕a.形容轻微的声音；b.形容颤抖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑟"},{"id":"glyph-kai-7470","script":"kai","character":"瑰","reading":"guī","description":"guī：(1)珍奇～异。～丽。～奇。～宝。～玮。～岸。～意琦行（赞颂卓越超人的思想和行为）。\n(2)次于玉的石头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑰"},{"id":"glyph-kai-7483","script":"kai","character":"璃","reading":"lí","description":"lí：〔玻～〕见玻”。\n〔琉～〕见琉”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璃"},{"id":"glyph-kai-74a7","script":"kai","character":"璧","reading":"bì","description":"bì：(1)平圆形中间有孔的玉，古代在典礼时用作礼器，亦可作饰物。\n(2)美玉的通称～人（即玉人”，指容貌秀美的人）。～日（像璧玉一样圆而亮的太阳）。～月。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璧"},{"id":"glyph-kai-74dc","script":"kai","character":"瓜","reading":"guā","description":"guā：蔓生植物，属葫芦科，果实可食西～。冬～。～蒂。～分（像切瓜一样分割，如～～天下”）。～葛。～代。～李（指嫌疑的境地）。～子儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓜"},{"id":"glyph-kai-74e2","script":"kai","character":"瓢","reading":"piáo","description":"piáo：(1)舀水或取东西的工具，多用对半剖开的匏瓜或木头制成～泼大雨。\n(2)形状像瓢的～虫。～儿菜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓢"},{"id":"glyph-kai-74e3","script":"kai","character":"瓣","reading":"bàn","description":"bàn：(1)组成花冠的各片花～。\n(2)植物的种子、果实或球茎可以分开的片状物豆～儿。蒜～儿。\n(3)物体破裂分成的部分。\n(4)量词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓣"},{"id":"glyph-kai-74e4","script":"kai","character":"瓤","reading":"ráng","description":"ráng：(1)瓜、柑橘等内部包着种子的部分西瓜～儿。橘子～儿。\n(2)某些东西皮或壳里包着的部分秫秸～。\n(3)方言，不好，软弱赶车的技术不～。病后身体～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓤"},{"id":"glyph-kai-74e6","script":"kai","character":"瓦","reading":"wǎ；wà","description":"wǎ：(1)用陶土烧成的～罐。～器。～釜雷鸣（喻无德无才的人占据高位，煊赫一时）。\n(2)用陶土烧成的覆盖房顶的东西～当（dāng）（即瓦筒之头）。～匠。\n〔～特〕电的功率单位。简称瓦”。\nwà：盖瓦这间房就等～瓦（wǎ）了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓦"},{"id":"glyph-kai-74f6","script":"kai","character":"瓶","reading":"píng","description":"píng：(1)口小腹大的器皿，多为瓷或玻璃做成，通常用来盛液体～子。酒～。花～。\n(2)量词，用于瓶装的东西两～啤酒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓶"},{"id":"glyph-kai-74f7","script":"kai","character":"瓷","reading":"cí","description":"cí：用高岭土烧成的一种质料，所做器物比陶器细致而坚硬陶～。～瓶。～壶。～碗。～器。～砖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓷"},{"id":"glyph-kai-7518","script":"kai","character":"甘","reading":"gān","description":"gān：(1)甜，味道好～甜。～苦。～冽。～落。～之如饴。同～共苦。～旨（美味的食物）。\n(2)美好～雨（适时而有益于农事的雨）。～霖。\n(3)自愿，乐意～愿。～拜下风。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甘"},{"id":"glyph-kai-751a","script":"kai","character":"甚","reading":"shèn；shén","description":"shèn：(1)很，极～好。～快。\n(2)超过日～一日。\n(3)方言，什么～事？\n(4)表示进一层的意思～至。～或。\nshén：同什2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甚"},{"id":"glyph-kai-751c","script":"kai","character":"甜","reading":"tián","description":"tián：像糖或蜜的滋味，喻使人感到舒服的，与苦”相对～品。～食。～菜。～瓜。～美。～润。～适。～爽。～言蜜语。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甜"},{"id":"glyph-kai-751f","script":"kai","character":"生","reading":"shēng","description":"shēng：(1)一切可以发育的物体在一定条件下具有了最初的体积和重量，并能发展长大诞～。滋～。～长。\n(2)造出～产。\n(3)活的，有活力的～存。～命。～物。～机。出～入死。舍～取义。\n(4)有生命的东西的简称众～。丧～。卫～。\n(5)生活，维持生活的～计。～意。\n(6)整个生活阶段一～。平～。今～。\n(7)发出，起动～病。～气。～效。～花之笔。谈笑风～。\n(8)使燃料燃烧起来～火。\n(9)植物果实不成熟～瓜。\n(10)未经烧煮或未烧煮熟的～饭。～水。\n(11)不熟悉的，不常见的～疏。～客。～字。陌～。\n(12)不熟练的～手。\n(13)未经炼制的。～铁。\n(14)硬态度～硬。～吞活剥。\n(15)甚，深～怕。～疼。\n(16)正在学习的人学～。门～。\n(17)有学问或有专业知识的人儒～。医～。\n(18)传统戏剧里扮演男子的角色小～。老～。武～。\n(19)词尾好～休养。\n(20)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-生"},{"id":"glyph-kai-7525","script":"kai","character":"甥","reading":"shēng","description":"shēng：〔外～〕姐妹的儿子，简作甥”，如～舅”。\n〔外～女〕姐妹的女儿，简作甥女”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甥"},{"id":"glyph-kai-7528","script":"kai","character":"用","reading":"yòng","description":"yòng：(1)使人或物发挥其功能使～。～心。～兵。～武。\n(2)可供使用的～品。～具。\n(3)进饭食的婉辞～饭。\n(4)花费的钱财费～。～项。～资。\n(5)物质使用的效果功～。有～之才。\n(6)需要（多为否定）不～多说。\n(7)因此～此。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-用"},{"id":"glyph-kai-7529","script":"kai","character":"甩","reading":"shuǎi","description":"shuǎi：(1)抡，扔～手。～开膀子（形容使出全部力气）。\n(2)抛开，抛去～卖。～闲话。\n(3)虫类下卵蚕蛾～子儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甩"},{"id":"glyph-kai-752b","script":"kai","character":"甫","reading":"fǔ","description":"fǔ：(1)古代在男子名字下加的美称，后指人的表字（亦作父”）台～（询问别人名号的礼貌用语）。\n(2)刚刚，才年～弱冠。惊魂～定。\n(3)大无田～田”（不要去耕大田）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甫"},{"id":"glyph-kai-7530","script":"kai","character":"田","reading":"tián","description":"tián：(1)种植农作物的土地～野。耕～。\n(2)和农业有关的～家。～园。\n(3)古同畋”，打猎。\n(4)古同佃”，耕作。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-田"},{"id":"glyph-kai-7531","script":"kai","character":"由","reading":"yóu","description":"yóu：(1)原因原～。事～。理～。～于（介词，表示原因或理由）。\n(2)自，从～表及里。～衷（出于本心）。\n(3)顺随，听从，归属～不得。信马～缰。\n(4)经过，经历必～之路。～来已久。\n(5)凭借～此可知。\n(6)古同犹”，尚且，还。\n(7)古同犹”，犹如，好像。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-由"},{"id":"glyph-kai-7532","script":"kai","character":"甲","reading":"jiǎ","description":"jiǎ：(1)天干的第一位，用于作顺序第一的代称～子。花～（六十岁的人）。\n(2)居于首位的，超过所有其它的～等。\n(3)古代科举考试成绩名次的分类一～（名为进士及第”）；二～（名为进士出身”）；三～（名为同进士出身”）。\n(4)古代军人打仗穿的护身衣服，用皮革或金属叶片制成盔～。～兵。～士。\n(5)现代用金属做成有保护功能的装备～板。装～车。\n(6)某些动物身上有保护功能的硬壳龟～。\n(7)手指或脚趾上的角质硬壳指～。\n(8)旧时户口编制单位保～。～长。\n(9)植物果实的外壳～坼（外表裂开）。\n(10)古同胛”，肩胛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甲"},{"id":"glyph-kai-7533","script":"kai","character":"申","reading":"shēn","description":"shēn：(1)地支的第九位，属猴。\n(2)用于记时～时（下午三点至五点）。\n(3)陈述，说明～述。～斥。～辩。～冤。三令五～。～请。～报。\n(4)重复，一再～之以盟誓，重之以昏姻”。\n(5)中国上海市的别称。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-申"},{"id":"glyph-kai-7535","script":"kai","character":"电","reading":"diàn","description":",其光曰电。”\n物理学名词","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-电"},{"id":"glyph-kai-7537","script":"kai","character":"男","reading":"nán","description":"nán：(1)阳性的人～性。～人。～孩。～女平等。\n(2)儿子长（zhǎng）～。\n(3)封建制度五等爵位的第五等～爵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-男"},{"id":"glyph-kai-7538","script":"kai","character":"甸","reading":"diàn；tián；shèng","description":"diàn：(1)古代指郊外的地方。\n(2)田野的出产物纳货贝于君，则曰纳～于有司”。\n(3)治理。\ntián：古同畋”，打猎。\nshèng：古同乘”，古代划分田、里的名称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甸"},{"id":"glyph-kai-753b","script":"kai","character":"画","reading":"huà","description":"绘画;作画\n善画者或兼\n⒈图图～儿。宣传～。连环～儿。\n⒉描绘，写描～。绘～。～图表。～人物。～个圈儿。叫你～押。\n⒊汉字的一笔叫\"一画\"\"札\"字是五画。\n⒋同\"划\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-画"},{"id":"glyph-kai-7545","script":"kai","character":"畅","reading":"chàng","description":"舒畅\n茂盛\n流畅,言辞敏捷、自在而流利\n正;极;甚\n①顺畅，没有阻碍～通无阻。痛快；尽情欢～。\n【畅所欲言】把想要说出的话痛痛快快地全说出来。\n【畅想】放开思路，无拘无束地想象～曲。\n【畅游】\n①尽情愉快地游览。\n②舒畅地游泳。\n⒈无阻碍～通。～达。～销。流～。\n⒉通晓晓～军事。\n⒊舒适舒～。欢～。\n⒋痛快，尽情～快。～谈。～所欲言。\n⒌盛～茂。～盛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畅"},{"id":"glyph-kai-754c","script":"kai","character":"界","reading":"jiè","description":"jiè：(1)边境，一个区域的边限～石（标志地界的石碑或石块）。～标。～址。～线（ａ．两个地区分界的线；ｂ．不同事物的分界；ｃ．某些事物的边缘）。～限（ａ．不同事物的分界；ｂ．尽头处，限度）。地～。\n(2)范围眼～。世～。自然～。\n(3)按职业或性别等所划的人群范围教育～。科学～。各～人士。\n(4)指大自然中动物、植物、矿物等的最大的类别无机～。有机～。\n(5)地层系统分类的最高一级，相当于地质年代中的代”。界”以下为系”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-界"},{"id":"glyph-kai-754f","script":"kai","character":"畏","reading":"wèi","description":"wèi：(1)怕～惧。～难（nán）。～罪。大无～。望而生～。\n(2)敬服敬～。～友（使人敬服的朋友）◇生可～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畏"},{"id":"glyph-kai-7554","script":"kai","character":"畔","reading":"pàn","description":"pàn：(1)田地的界限。\n(2)边河～〓～。桥～。耳～。枕～。\n(3)古同叛”。\n〔～援〕横暴，跋扈，如帝谓文王，无然～～。”亦称畔换”、叛换”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畔"},{"id":"glyph-kai-7559","script":"kai","character":"留","reading":"liú","description":"liú：(1)停止在某一个地方停～。～学。～任。～级。～步。～守。～驻。\n(2)注意力放在上面～心。～神。～意。\n(3)不忍舍弃，不忍离去～连。～恋。\n(4)不使离开～客。～宿。挽～。拘～。\n(5)接受收～。\n(6)保存保～。～存。～别。～念。～后路。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-留"},{"id":"glyph-kai-755c","script":"kai","character":"畜","reading":"chù；xù","description":"xù：养禽兽～产。～牧。～养。\nchù：禽兽，有时专指家养的禽兽～肥。～力。～疫。幼～。牲～。家～。～生。六～兴旺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畜"},{"id":"glyph-kai-7565","script":"kai","character":"略","reading":"lüè","description":"lüè：(1)大致，简单，不详细大～。简～。粗～。～微。～有所闻。～知一二。\n(2)省去，简化省～■～。其余从～。\n(3)简要的叙述史～。要～。事～。\n(4)计谋方～。策～。战～。\n(5)抢，掠夺侵～。攻城～地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-略"},{"id":"glyph-kai-756a","script":"kai","character":"番","reading":"fān；pān","description":"fān：(1)遍数，次，回三～五次。\n(2)轮流更代轮～。更（gēng）～。\n(3)称外国的或外族的～邦。～茄。～薯。\n(4)倍产量翻了二～。\npān：〔～禺〕地名，在中国广东省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-番"},{"id":"glyph-kai-7574","script":"kai","character":"畴","reading":"chóu","description":"特指种麻的田\n同类,类别◇作俦”\n①田地田～、平～千里。\n②种类范～。\n⒈田地田～。\n⒉类，同类，类别范～。物各有～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畴"},{"id":"glyph-kai-7578","script":"kai","character":"畸","reading":"jī","description":"jī：(1)不规则的，不正常的～形。～胎。～人。～变。\n(2)残余，零星～数。～零。～羡（指剩余）。\n(3)偏～轻～重。\n(4)古同奇”，数目不成双的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畸"},{"id":"glyph-kai-7586","script":"kai","character":"疆","reading":"jiāng；qiáng","description":"jiāng：(1)地域，领域，边界～土。～宇（国土）。～界。～场（战场）。～陲（边境）。边～。～。\n(2)极限万寿无～。\n(3)划分界限楚子～之”。\nqiáng：古同彊（强）”，强大。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疆"},{"id":"glyph-kai-758f","script":"kai","character":"疏","reading":"shū","description":"shū：(1)去掉阻塞使通畅～导。～通。～浚。～解（jiě）。\n(2)分散～散。仗义～财。\n(3)事物间距离大，空隙大，与密”相对～密。～松。～朗。～旷。～阔。～落（luò）。稀～。天网恢恢，～而不漏。\n(4)不亲密，关系远的亲～。～远。\n(5)不细密，忽略～忽。\n(6)空虚志大才～。\n(7)不熟悉生～。\n(8)粗劣～食。～粝。\n(9)古同蔬”，蔬菜。\n(10)分条说明的文字上～（臣子向帝王分条陈述的意见书）。奏～。注～（对古书的注解和对注解的注释）。\n(11)僧道拜忏时所焚化的祝告文。\n(12)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疏"},{"id":"glyph-kai-7591","script":"kai","character":"疑","reading":"yí；nǐ","description":"yí：(1)不信，猜度（duó）～惑。～问。～心。～团。～虑。～窦。～点。～端。猜～。怀～。半信半～。\n(2)不能解决的，不能断定的～案。～难。～义。存～。\n信；\nnǐ：(1)安定，止息。\n(2)古同拟”，比拟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疑"},{"id":"glyph-kai-7597","script":"kai","character":"疗","reading":"liáo","description":"治愈,治好;止","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疗"},{"id":"glyph-kai-7599","script":"kai","character":"疙","reading":"gē；yì","description":"gē：〔～瘩〕ａ．皮肤上突起或肌肉上结成的病块，如头上起了个～～”；ｂ．小球形或块状的东西，如芥菜～～”；ｃ．不易解决的问题，如思想～～”；ｄ．不通畅或不爽利，如这篇作文中的语句很～～”；ｅ．量词，如一～～糕”；ｆ．麻烦，别扭。均亦作疙疸”（瘩”、疸”均读轻声）。\nyì：痴呆的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疙"},{"id":"glyph-kai-759a","script":"kai","character":"疚","reading":"jiù","description":"jiù：(1)长期生病。\n(2)忧苦，特指因自己过失而造成的心内痛苦负～。内～。愧～。歉～。内省（xǐng）不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疚"},{"id":"glyph-kai-759f","script":"kai","character":"疟","reading":"nüè","description":"通虐”。残暴;灾害\n受虐待\n义同疟”,只用于疟子”\n～、三日～、恶性～等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疟"},{"id":"glyph-kai-75a4","script":"kai","character":"疤","reading":"bā","description":"bā：(1)伤口或疮平复以后留下的痕迹伤～。疮～。～痕。\n(2)器物上像疤的痕迹坛子磕了一个～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疤"},{"id":"glyph-kai-75ab","script":"kai","character":"疫","reading":"yì","description":"yì：流行性急性传染病瘟～。鼠～。防～。检～。～情。免～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疫"},{"id":"glyph-kai-75ae","script":"kai","character":"疮","reading":"chuāng","description":"痈、瘫、疽、疖等的总称\n伤口;外伤。也作创”\n喻指伤痛;痛苦\n疮 chuāng通常指皮肤上或粘膜上发生溃烂的疾病。\n【疮痍满目】见【满目疮痍】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疮"},{"id":"glyph-kai-75af","script":"kai","character":"疯","reading":"fēng","description":"瘫痪\n神经错乱,精神失常\n形容任性放荡,不受管束或无节制地嬉笑哄闹\n指农作物生长旺盛但不结果实\n⒉〈喻〉农作物生长旺盛，但不结果实油菜苗长～了。\n⒊〈喻〉狂妄，猖狂说～话。消灭～狂的敌人。\n⒋瘫痪～瘫。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疯"},{"id":"glyph-kai-75b2","script":"kai","character":"疲","reading":"pí","description":"pí：(1)身体劳累的感觉～乏。～倦。～劳。～惫。～敝。精～力尽。\n(2)懈怠，不起劲～塌。～软。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疲"},{"id":"glyph-kai-75b9","script":"kai","character":"疹","reading":"zhěn","description":"zhěn：皮肤上起的小颗粒，通常是红色，多由皮肤表层发炎浸润而起湿～。麻～（亦称疹子”）。风～。丘～。疱～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疹"},{"id":"glyph-kai-75bc","script":"kai","character":"疼","reading":"téng","description":"téng：(1)因病、刺激或创伤而起的难受的感觉～痛。头～。\n(2)喜爱，爱惜～爱。～惜。心～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疼"},{"id":"glyph-kai-75be","script":"kai","character":"疾","reading":"jí","description":"jí：(1)病，身体不舒适～病。目～。残～。讳～忌医。\n(2)一般的痛苦～苦。\n(3)疼痛～首蹙额。\n(4)恨～恶如仇。\n(5)古同嫉”，妒忌。\n(6)弊病，缺点寡人有～”。\n(7)快，迅速～步。～走。～进。～驰。～足先得。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疾"},{"id":"glyph-kai-75c5","script":"kai","character":"病","reading":"bìng","description":"bìng：(1)生物体发生不健康的现象疾～。～症。～例。～痛。～情。～源。～愈。～变。～危。～逝。～榻。～残。\n(2)缺点，错误语～。通～。弊～。\n(3)损害，祸害祸国～民。\n(4)不满，责备诟～。\n(5)烦躁，担忧郑人～之”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-病"},{"id":"glyph-kai-75c7","script":"kai","character":"症","reading":"zhèng；zhēng","description":"zhèng：疾病表现出来的情况，如症状、病症。zhēng：古代指腹中结块的病，今见“症结”，比喻问题的关键。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-75ca","script":"kai","character":"痊","reading":"quán","description":"quán：病好了，恢复健康～愈。～可。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痊"},{"id":"glyph-kai-75d2","script":"kai","character":"痒","reading":"yǎng","description":"形容某些难以抑制的强烈愿望\n痒yáng 1.忧思过度所成之病。 2.受损害;损害。 3.通\"疡\"。痈疮。参见\"痒疥\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痒"},{"id":"glyph-kai-75d5","script":"kai","character":"痕","reading":"hén","description":"hén：创伤痊愈后留下的疤，亦泛指斑迹～印。～迹。～瘕（疤痕。喻曾犯有罪案的人）。伤～。泪～。裂～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痕"},{"id":"glyph-kai-75d8","script":"kai","character":"痘","reading":"dòu","description":"dòu：〔～疮〕即天花”。\n〔牛～〕牛身上的痘疮，制成疫苗后接种在人身上，可以预防天花。\n〔水～〕急性传染病。小儿易感染。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痘"},{"id":"glyph-kai-75db","script":"kai","character":"痛","reading":"tòng","description":"tòng：(1)疾病、创伤等引起的难受的感觉头～。肚子～。～风。～痒（ａ．喻疾苦，如～～相关”；ｂ．喻紧要的事，如不关～～”）。\n(2)悲伤悲～。哀～。～楚。～惜。～不欲生。\n(3)尽情地，深切地，彻底地～击。～悼。～责。～快。～改前非。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痛"},{"id":"glyph-kai-75e2","script":"kai","character":"痢","reading":"lì","description":"lì：(1)中医学病名，古称滞下”。又因病情不同而有赤～”、白～”、赤白～”、噤口～”等名。\n(2)见瘌”字瘌痢”。\n〔～疾〕传染病。症状有大便频繁，腹痛，发热，粪便带脓、血和黏液等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痢"},{"id":"glyph-kai-75ea","script":"kai","character":"痪","reading":"huàn","description":"huàn：〔瘫～〕见瘫”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痪"},{"id":"glyph-kai-75f0","script":"kai","character":"痰","reading":"tán","description":"tán：气管、支气管或肺泡黏膜分泌出来的黏液～喘。～厥。～盂。吐～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痰"},{"id":"glyph-kai-75f4","script":"kai","character":"痴","reading":"chī","description":"chī：(1)傻，无知～人说梦。～钝。～愚。白～。\n(2)精神失常，疯癫发～。～癫。\n(3)入迷，极度迷恋～心。～情。\n(4)谦辞，白白地～长（zhǎng）（说自己白白地比对方大若干岁）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痴"},{"id":"glyph-kai-75f9","script":"kai","character":"痹","reading":"bì","description":"bì：〔～症〕中医指由风、寒、湿等引起的肢体疼痛或麻木的病。\n〔麻～〕见麻”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痹"},{"id":"glyph-kai-761f","script":"kai","character":"瘟","reading":"wēn","description":"wēn：(1)中医指流行性急性传染病～疫。～病。～疹。\n(2)指戏曲沉闷乏味这场戏唱～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘟"},{"id":"glyph-kai-7624","script":"kai","character":"瘤","reading":"liú","description":"liú：身体组织增殖生成的赘生物，多由刺激或微生物寄生而起～子。肉～。肿～。根～。～胃（反刍动物的胃的一部分）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘤"},{"id":"glyph-kai-7626","script":"kai","character":"瘦","reading":"shòu","description":"shòu：(1)体内含脂肪少，肌肉不丰满，与胖”、肥”相对～溜（溜”读轻声）。～弱。～小。～削。～俏。～长（cháng）。～瘪。消～。清～。～骨嶙峋。\n(2)衣服鞋袜等窄小这条裤子太～了。\n(3)细削，单薄字小而～。\n(4)土地瘠薄～瘠。\n(5)遒劲有骨力书贵～硬。水清石～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘦"},{"id":"glyph-kai-7629","script":"kai","character":"瘩","reading":"dá","description":"dá：〔～背〕中医指生在背部的痈。亦称搭手”。\nd：〔疙～〕见疙”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘩"},{"id":"glyph-kai-762a","script":"kai","character":"瘪","reading":"biě","description":"用同憋”。闷\n瘪三\n瘪 biē又见biě\n【瘪三】。乞讨或偷窃为生的游民的鄙称。\n瘪 biě物体表面凹下去；不饱满～谷子、车带～了。又见biē。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘪"},{"id":"glyph-kai-762b","script":"kai","character":"瘫","reading":"tān","description":"肌肉失去活动能力，如瘫痪；也比喻机构或系统不能正常运转。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-7638","script":"kai","character":"瘸","reading":"qué","description":"qué：腿脚有毛病，行步时身体不平衡～腿。一～一拐。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘸"},{"id":"glyph-kai-763e","script":"kai","character":"瘾","reading":"yǐn","description":"泛指浓厚的兴趣\n⒈特别深的嗜好烟～。酒～。\n⒉浓厚的兴趣她看书看上了～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘾"},{"id":"glyph-kai-764c","script":"kai","character":"癌","reading":"ái","description":"ái：人及动物身体由于某些因素的作用，细胞恶性增生而形成的恶性肿瘤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-癌"},{"id":"glyph-kai-7663","script":"kai","character":"癣","reading":"xuǎn","description":"癣xuǎn感染霉菌后引起的皮肤病头～。脚～。花斑～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-癣"},{"id":"glyph-kai-7678","script":"kai","character":"癸","reading":"guǐ","description":"guǐ：天干的第十位，用于作顺序第十的代称。\n〔～水〕指月经。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-癸"},{"id":"glyph-kai-767b","script":"kai","character":"登","reading":"dēng","description":"dēng：(1)上，升～山。～车。～门。～天。～台。～场（chǎng）。～高。～攀。～临。～科。～程。～堂入室。\n(2)踩，践踏，脚向下用力～踏。踢～。\n(3)记载～记。～报。～载。\n(4)谷物成熟～岁（丰年）。五谷丰～。\n(5)立刻～时。～即相许和，便可作婚姻。”\n(6)进～崇（进用推崇）。\n(7)方言，穿～上靴子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-登"},{"id":"glyph-kai-767d","script":"kai","character":"白","reading":"bái","description":"bái：(1)雪花或乳汁那样的颜色～色。～米。\n(2)明亮～昼。～日做梦。\n(3)清楚明～。不～之冤。\n(4)纯洁一生清～。～璧无瑕。\n(5)空的，没有加上其它东西的空～。～卷。\n(6)没有成就的，没有效果的～忙。～说。\n(7)没有付出代价的～吃～喝。\n(8)陈述自～。道～（亦称说白”、白口”）。\n(9)与文言相对～话文。\n(10)告语告～（对公众的通知）。\n(11)丧事红～喜事（婚事和丧事）。\n(12)把字写错或读错～字（别字）。\n(13)政治上反动的～匪。～军。\n(14)中国少数民族，主要分布于云南省～族。～剧。\n(15)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-白"},{"id":"glyph-kai-767e","script":"kai","character":"百","reading":"bǎi","description":"bǎi：(1)数名，十个十（在钞票和单据上常用大写佰”代）～步穿杨。～儿八十。～分比。\n(2)喻很多～草。～货。～姓（人民）。～般。～炼成钢。～无聊赖。～废俱兴（xīng）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-百"},{"id":"glyph-kai-7682","script":"kai","character":"皂","reading":"zào","description":"zào：(1)黑色～靴。不分～白（喻不问是非）。\n(2)差役～隶（古代贱役，后专以称衙门里的差役）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皂"},{"id":"glyph-kai-7684","script":"kai","character":"的","reading":"de；dí；dì","description":"dí：真实，实在～确。～当（dàng）。～情。～真。～证。\ndì：箭靶的中心中（zhòng）～。有～放矢。众矢之～。目～（要达到的目标、境地）。\nde：(1)用在词或词组后表明形容词性美丽～。\n(2)代替所指的人或物唱歌～。\n(3)表示所属的关系的词他～衣服。\n(4)助词，用在句末，表示肯定的语气，常与是”相应这句话是很对～。\n(5)副词尾，同地2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-的"},{"id":"glyph-kai-7686","script":"kai","character":"皆","reading":"jiē","description":"jiē：全，都～大欢喜。人人～知。放之四海而～准。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皆"},{"id":"glyph-kai-7687","script":"kai","character":"皇","reading":"huáng","description":"huáng：(1)君主，亦指神话传说中的神～帝。～后。～宫。～储（已确定的皇位继承人）。～权。\n(2)大～～巨著。冠冕堂～。\n(3)对先代的敬称～考（对亡父的尊称）。\n(4)古同遑”，闲遐。\n(5)古同惶”，恐惧。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皇"},{"id":"glyph-kai-7693","script":"kai","character":"皓","reading":"hào","description":"hào：(1)洁白，明亮～白。～齿。～首穷经。～月当空。\n(2)古同昊”，昊天。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皓"},{"id":"glyph-kai-7696","script":"kai","character":"皖","reading":"wǎn","description":"wǎn：中国安徽省的别称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皖"},{"id":"glyph-kai-76ae","script":"kai","character":"皮","reading":"pí","description":"pí：(1)动植物体表的一层组织～毛。\n(2)兽皮或皮毛的制成品裘～。\n(3)包在外面的一层东西封～。书～。\n(4)表面地～。\n(5)薄片状的东西豆腐～。\n(6)韧性大，不松脆花生放～了。\n(7)不老实，淘气顽～。\n(8)指橡胶胶～。～球。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皮"},{"id":"glyph-kai-76b1","script":"kai","character":"皱","reading":"zhòu","description":"衣、物等经折叠而显出痕迹\n收缩;紧蹙\n⒈皮肤上起的褶纹满脸～纹。〈引〉物体上的褶纹衣服～了。\n⒉使生褶纹紧～眉头。\n皱zhōu 1.栗蓬，包在栗子外面的多刺壳斗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皱"},{"id":"glyph-kai-76bf","script":"kai","character":"皿","reading":"mǐn","description":"mǐn：碗、碟、杯、盘一类用器的统称器～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皿"},{"id":"glyph-kai-76c6","script":"kai","character":"盆","reading":"pén","description":"pén：(1)盛放东西或洗涤的用具～景。～花。～栽。脸～。澡～。\n(2)中央凹入像盆状的东西～地。骨～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盆"},{"id":"glyph-kai-76c8","script":"kai","character":"盈","reading":"yíng","description":"yíng：(1)充满～满。～溢。充～。沸反～天。\n(2)多余～余。～亏。～利。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盈"},{"id":"glyph-kai-76ca","script":"kai","character":"益","reading":"yì","description":"yì：(1)增加～寿延年。增～。损～。\n(2)好处，有好处利～。～处。公～。权～。受～非浅。\n(3)更加～发。日～壮大。\n(4)古同溢”，水漫出来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-益"},{"id":"glyph-kai-76cf","script":"kai","character":"盏","reading":"zhǎn","description":"酒、茶或灯的计量单位\n⒈浅而小的杯子酒～。茶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盏"},{"id":"glyph-kai-76d0","script":"kai","character":"盐","reading":"yán","description":"由金属\n⒈盐，又叫\"咸～\" ，主要化学成份是氯化钠。放在食品里使有咸味加碘食～。\n⒉盐类，化学上的中性化合物。它是酸类中的氢根被金属元素置换而成。\n盐yàn 1.用盐腌物。 2.指海水﹑盐水等淹﹑浸。 3.通\"艳\"。羡慕。 4.通\"艳\"。美好。 5.古乐曲名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盐"},{"id":"glyph-kai-76d1","script":"kai","character":"监","reading":"jiān","description":"以监其上下之所好。”\n王怒,\n⒈察看，督察，从上看下～督。～察。～观四方。\n⒉牢，狱～牢。～狱。坐～房。\n监kàn 1.地名用字。参见\"监乡\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-监"},{"id":"glyph-kai-76d2","script":"kai","character":"盒","reading":"hé","description":"hé：底盖相合的盛东西的器物～子。果～儿。铅笔～儿。～带（盒式磁带的简称）。～饭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盒"},{"id":"glyph-kai-76d4","script":"kai","character":"盔","reading":"kuī","description":"kuī：(1)用来保护头的帽子，多用金属制成头～。钢～。～甲。\n(2)形状像盔或半个球形的帽～儿。～头（头”读轻声）。\n(3)盆子一类的器皿瓦～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盔"},{"id":"glyph-kai-76d6","script":"kai","character":"盖","reading":"gài","description":"苫,用茅草编成的遮盖物,可以蔽体或覆屋顶\n雨伞\n车篷\n庭有枇杷\n⒈遮蔽器物的东西茶杯～。瓶～子。锅～儿。\n⒉〈古〉遮阳遮雨的用具华～。\n⒊遮掩，蒙上覆～。～住。～被子。\n⒋建筑～房子。～高楼。\n⒌打上～手印。～公章。\n⒍压倒，超过，没有人比得上气～山河。功～五帝。～世英雄。\n⒎动物的甲壳龟～。蟹～。\n⒏文言虚词。\n①发语词～闻。\n②大概～近年之事。\n③连词。〈表〉原因为何不知，～未学也。\n⒐〈古〉通\"盍\"∥不。\n⒑见gě。\n⒈姓。\n⒉见gài。\n盖hé 1.通\"盍\"∥不。 2.通\"盍\"∥。 3.通\"阖\"。门扇。\n盖hài 1.桅。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盖"},{"id":"glyph-kai-76d7","script":"kai","character":"盗","reading":"dào","description":"dào：(1)偷窃，用不正当的手段营私或谋取～窃。～贼。～伐。～掘。～运。～卖。～用。～名欺世（亦称欺世盗名”）。\n(2)偷窃或抢劫财物的人海～。强～。窃国大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盗"},{"id":"glyph-kai-76d8","script":"kai","character":"盘","reading":"pán","description":"古代的一种盥洗用具\n形状或功用像盘子的东西\n⒉形状或功用像盘子的脸～儿。算～。轮～。磨～。棋～。\n⒊回绕，弯曲～旋。～香。～膝。～山道。\n⒋垒，砌～灶。～炕。\n⒍指市场上成交的价格开～。收～。平～儿。\n⒎量词下完了两～棋。买回了三～录像带。\n盘xuán 1.漩涡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盘"},{"id":"glyph-kai-76db","script":"kai","character":"盛","reading":"shèng；chéng","description":"shèng：(1)兴旺兴～。繁～。旺～。～世。～衰。茂～。全～时期。\n(2)炽烈年轻气～。～怒。～气凌人。\n(3)丰富，华美～产。～宴。～装。\n(4)热烈，规模大～大。～况。～典。～举。\n(5)广泛，程度深～传（chuán）。～行（xíng）。～赞。～名。～夏。\n(6)深厚～意。\n(7)姓。\n衰；\nchéng：(1)把东西放进去～饭。\n(2)容纳～器。小桶～不下多少东西。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盛"},{"id":"glyph-kai-76df","script":"kai","character":"盟","reading":"méng","description":"méng：(1)旧时指宣誓缔约，现指阶级的联合，国与国的联合～军。～友。同～国。～约。山～海誓。\n(2)指结拜弟兄～兄。～弟。\n(3)中国内蒙古自治区的行政单位。\n(4)发（誓）～誓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盟"},{"id":"glyph-kai-76ee","script":"kai","character":"目","reading":"mù","description":"mù：(1)眼睛～光。醒～。历历在～。～指气使（用眼光和气色示意以役使别人，形容骄横傲慢的神志。亦作颐指气使”）。\n(2)看，视～语。～论（喻没有自知之明或浅陋狭隘的见解）。\n(3)想要达到的地点、境地或想要得到的结果～的（dì）（亦指箭靶的中心）。\n(4)大项中再分的小项条～。纲举～张。\n(5)名称数～。巧立名～。\n(6)标题～录。\n(7)生物学分类系统上所用的等级之一，在纲”以下，科”以上鸟纲中有雁形～和鸡形～。\n(8)孔眼网～。\n(9)指为首的人头～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-目"},{"id":"glyph-kai-76ef","script":"kai","character":"盯","reading":"dīng","description":"dīng：注视，集中视力看着，不放松～视。～梢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盯"},{"id":"glyph-kai-76f2","script":"kai","character":"盲","reading":"máng","description":"máng：瞎，看不见东西，对事物不能辨认～从。～动。～目。～人。～区（指雷达、探照灯、胃镜等探测或观察不到的区域）。～流。～人瞎马（喻处境非常危险）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盲"},{"id":"glyph-kai-76f4","script":"kai","character":"直","reading":"zhí","description":"zhí：(1)不弯曲～线。～角。～径。～立。～截了当。～觉（jué）。～观。\n(2)把弯曲的伸开～起腰来。\n(3)公正合理是非曲～。理～气壮。耿～。正～。\n(4)爽快，坦率～爽。～率（shuài）。～谏。～诚。～言不讳。\n(5)一个劲儿地，连续不断一～走。～哭。\n(6)竖，与横”相对不要横着写，要～着写。\n(7)汉字笔形之一，自上至下。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-直"},{"id":"glyph-kai-76f8","script":"kai","character":"相","reading":"xiāng；xiàng","description":"xiāng：互相；表示对对方的行为。xiàng：相貌、形态；观察察看；古代辅佐君主的官职。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-76f9","script":"kai","character":"盹","reading":"dǔn","description":"dǔn：很短时间的睡眠打～儿。冲（chòng）～儿。醒～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盹"},{"id":"glyph-kai-76fc","script":"kai","character":"盼","reading":"pàn","description":"pàn：(1)希望，想望～望。切～。\n(2)看，引申为看待流～。左顾右～。\n(3)眼睛白黑分明～倩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盼"},{"id":"glyph-kai-76fe","script":"kai","character":"盾","reading":"dùn","description":"dùn：(1)古代打仗时防护身体，挡住敌人刀箭等的牌～牌（亦喻推托的借口）◇～。\n(2)盾形的东西（多指硬币上的纹章）金～。银～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盾"},{"id":"glyph-kai-7701","script":"kai","character":"省","reading":"shěng；xǐng","description":"shěng：节约，减免；行政区划名。xǐng：反省、察看；醒悟，如自省、省亲、不省人事。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-7709","script":"kai","character":"眉","reading":"méi","description":"méi：(1)眼上额下的毛～毛。～宇（两眉上面的地方）。～心。～目。～寿（长寿）。～睫。扬～吐气。\n(2)书页上端的空白书～。～批。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眉"},{"id":"glyph-kai-770b","script":"kai","character":"看","reading":"kàn；kān","description":"kàn：(1)使视线接触人或物～见。～书。～齐。\n(2)观察，判断～病。观～。～好（根据市场情况，估计某种商品好销）。～透（透彻深刻地了解或认识。亦称看破”、看穿”）。～风使舵。\n(3)访问，拜望～望。～朋友。\n(4)照应，对待～重（zhòng）。～轻。～待。\n(5)想，以为～法。\n(6)先试试以观察它的结果做做～。\n(7)提防，小心别跑，～摔着。\n(8)安排～茶。～酒。～座。\n瞅；顾；观；瞥；瞧；视；望；\nkān：守护，监视～护。～押。～门。～青（看守正在结实还未成熟的庄稼）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-看"},{"id":"glyph-kai-771f","script":"kai","character":"真","reading":"zhēn","description":"zhēn：(1)与客观事实相符合，与假”、伪”相对～诚。～谛。～挚。～心。逼～。认～。～才实学。～知灼见。\n(2)确实，的确～好。～正。～切。\n(3)清楚，显明看得～。咬字很～。\n(4)本性，本原纯～。天～。\n(5)人的肖像传（chuán）～。写～。\n(6)汉字的楷书～字。～书。～草隶篆。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-真"},{"id":"glyph-kai-7720","script":"kai","character":"眠","reading":"mián","description":"mián：(1)睡觉安～。长～。失～。\n(2)某些动物一定时期内像睡眠那样不食不动初～。冬～。\n(3)倒卧一日三～三起。\n(4)横放～琴绿阴”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眠"},{"id":"glyph-kai-7728","script":"kai","character":"眨","reading":"zhǎ","description":"zhǎ：眼睛很快地一闭一开～眼。一～眼（形容时间短）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眨"},{"id":"glyph-kai-772f","script":"kai","character":"眯","reading":"mī；mí","description":"mī：(1)眼皮微微合拢～缝双目。笑～了眼。\n(2)小睡～一会儿。\nmí：尘土入眼，不能睁开看东西让沙子～了眼睛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眯"},{"id":"glyph-kai-7736","script":"kai","character":"眶","reading":"kuàng","description":"kuàng：眼的四周眼～。热泪盈～。泪水夺～而出。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眶"},{"id":"glyph-kai-7737","script":"kai","character":"眷","reading":"juàn","description":"juàn：(1)顾念，爱恋～念。～恋。～顾。～注（爱护关注）。～～（依恋的样子）。\n(2)亲属亲～。女～。～属。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眷"},{"id":"glyph-kai-773c","script":"kai","character":"眼","reading":"yǎn","description":"yǎn：(1)人和动物的视觉器官～睛。～底。～力。～色。～神。～帘。～目。～疾手快。\n(2)见识，对事物的看法～光远大。～界开阔。\n(3)孔洞，窟窿炮～。针～儿。泉～。\n(4)关节，要点节骨～儿。字～儿。\n(5)戏曲中的节拍一板三～。\n(6)当前～前利益。～下。\n(7)量词一～井。\n(8)围棋术语，一方子中所留的空儿，在这个空儿中对方不能下成活棋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-眼"},{"id":"glyph-kai-7740","script":"kai","character":"着","reading":"zhe；zháo；zhuó；zhāo","description":"zhe：助词，表示动作持续或状态保持。zháo：接触上；燃烧；入睡，如着火、睡着。zhuó：穿、接触或施加，如着装、着力。zhāo：下棋的一步或办法，如高着。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-7741","script":"kai","character":"睁","reading":"zhēng","description":"zhēng：张开眼睛～眼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睁"},{"id":"glyph-kai-7750","script":"kai","character":"睐","reading":"lài","description":"瞳仁不正\n旁视,斜视\n眺望","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睐"},{"id":"glyph-kai-775b","script":"kai","character":"睛","reading":"jīng","description":"jīng：眼球，眼珠眼～。目不转～。画龙点～。定～一看。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睛"},{"id":"glyph-kai-7761","script":"kai","character":"睡","reading":"shuì","description":"shuì：闭目安息，大脑皮质处于休息状态～意。～觉。～梦。～眠。入～。～魔（喻强烈的睡意）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睡"},{"id":"glyph-kai-7763","script":"kai","character":"督","reading":"dū","description":"dū：(1)察看；监管监～。～办。～导。～察。～促。～师。～率（shuài）（亦作督帅”）。～战。～学。\n(2)责罚～过（督察责备）。～责。\n(3)古代将官名都～。～邮。～护。总～。提～。～抚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-督"},{"id":"glyph-kai-7766","script":"kai","character":"睦","reading":"mù","description":"mù：(1)和好，亲近和～。～邻。兄弟不～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睦"},{"id":"glyph-kai-776b","script":"kai","character":"睫","reading":"jié","description":"jié：(1)眼睑边缘的细毛～毛。目不交～。迫在眉～。\n(2)眨眼矢来注眸子而眶不～。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睫"},{"id":"glyph-kai-776c","script":"kai","character":"睬","reading":"cǎi","description":"cǎi：理会，答理理～。～也不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睬"},{"id":"glyph-kai-7779","script":"kai","character":"睹","reading":"dǔ","description":"dǔ：看见目～。先～为快。耳闻目～。熟视无～。有目共～。～物思人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-睹"},{"id":"glyph-kai-7784","script":"kai","character":"瞄","reading":"miáo","description":"miáo：把视力集中在一点上，注意看～准。猫总～着那条鱼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞄"},{"id":"glyph-kai-7785","script":"kai","character":"瞅","reading":"chǒu","description":"chǒu：看～见（看见）。～空（看机会，找闲空）。～睬（答理）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞅"},{"id":"glyph-kai-778e","script":"kai","character":"瞎","reading":"xiā","description":"xiā：(1)眼睛看不见东西～子≮灯～火。\n(2)胡，乱，没来由～忙。～话。～吹。～聊。一堆～线团。\n(3)炮弹打出去不爆炸～炮。～火。\n(4)农作物子粒不饱满～穗。～高粱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞎"},{"id":"glyph-kai-7792","script":"kai","character":"瞒","reading":"mán","description":"通满”\n通颟”\n隐藏实情\n瞒mén 1.惭愧。参见\"瞒然\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞒"},{"id":"glyph-kai-77a7","script":"kai","character":"瞧","reading":"qiáo","description":"qiáo：看～见。～病。～热闹。～不起。～得起。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞧"},{"id":"glyph-kai-77a9","script":"kai","character":"瞩","reading":"zhǔ","description":"见;看见","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞩"},{"id":"glyph-kai-77aa","script":"kai","character":"瞪","reading":"dèng","description":"dèng：(1)怒目直视～眼。～视。\n(2)睁大眼睛发呆目～口呆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞪"},{"id":"glyph-kai-77ac","script":"kai","character":"瞬","reading":"shùn","description":"shùn：(1)眨眼，眼球一动尔先学不～，而后可言射矣”。一～即逝。\n(2)极短的时间转～。～间。～时。～即。～华（指短暂的时光）。～息。～时速度。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞬"},{"id":"glyph-kai-77ad","script":"kai","character":"瞭","reading":"hóu","description":"瞭hóu 1.半盲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞭"},{"id":"glyph-kai-77b3","script":"kai","character":"瞳","reading":"tóng","description":"tóng：懵懵懂懂，瞪着眼看的样子汝～焉如新生之犊”。\n〔～孔〕虹膜中央的小孔，光线通过瞳孔进入眼内。通称瞳子”、瞳人”、瞳仁”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞳"},{"id":"glyph-kai-77bb","script":"kai","character":"瞻","reading":"zhān","description":"zhān：往上或往前看～仰。～望。～拜。～谒。～念。～前顾后。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瞻"},{"id":"glyph-kai-77d7","script":"kai","character":"矗","reading":"chù","description":"chù：直立，高耸～立。～～（高耸的样子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矗"},{"id":"glyph-kai-77db","script":"kai","character":"矛","reading":"máo","description":"máo：古代用来刺杀敌人的长柄兵器～头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矛"},{"id":"glyph-kai-77e2","script":"kai","character":"矢","reading":"shǐ","description":"shǐ：(1)箭流～。弓～。有的（dì）放～。～镞。\n(2)誓～志不渝（发誓立志，永不改变）。\n(3)正直～言（正直的言论）。\n(4)陈列公～鱼于棠”。\n(5)施布～其文德”。\n(6)古代投壶（一种娱乐活动）用的筹。\n(7)古同屎”，粪便。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矢"},{"id":"glyph-kai-77e3","script":"kai","character":"矣","reading":"yǐ","description":"yǐ：文言助词（ａ．用于句末，与了”相同，如由来久～”，悔之晚～”；ｂ．表示感叹，如大～哉”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矣"},{"id":"glyph-kai-77e5","script":"kai","character":"知","reading":"zhī；zhì","description":"zhī：(1)晓得，明了～道。～名（著名）。～觉（有感觉而知道）。良～。～人善任。温故～新。～难而进。～情达理。\n(2)使知道通～。～照。\n(3)学识，学问～识，求～。无～。\n(4)主管～县（旧时的县长）。～府。～州。～宾（指主管招待宾客的人。亦称知客”）。\n(5)彼此了解相～。～音。～近。\n(6)彼此了解、交好的人故～（老朋友）。\nzhì：古同智”，智慧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-知"},{"id":"glyph-kai-77e9","script":"kai","character":"矩","reading":"jǔ；jv","description":"jǔ：(1)画直角或方形的工具～尺（曲尺）。～形（长方形）。力～（物理学上指使物体转动的力乘以到转轴的距离）。规～。\n(2)法则，规则循规蹈～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矩"},{"id":"glyph-kai-77eb","script":"kai","character":"矫","reading":"jiǎo","description":"凡事别矫情\n矫〈动〉\n把弯曲的物体弄直\n匡正;纠正\n以身矫之。\n⒈将弯曲的东西弄直～正曲木。〈引〉纠正～枉过正。～正了偏差。\n⒉假托，诈称～令。\n⒊强，勇武～健的步伐。～捷。\n矫jiāo 1.古代投壶，箭从壶中跃出而手接之复投谓之\"矫\"。也称为\"骁\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矫"},{"id":"glyph-kai-77ed","script":"kai","character":"短","reading":"duǎn","description":"duǎn：(1)长度小，与长（cháng）”相对～期。～暂。～促。～途。～命。～讯。～浅。～兵相接。～小精悍。\n(2)缺少，欠～少。～缺。\n(3)缺点～处。护～。取长补～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-短"},{"id":"glyph-kai-77ee","script":"kai","character":"矮","reading":"ǎi","description":"ǎi：(1)人的身材短～人。～矬。～个儿。～墩墩。\n(2)高度小～林。～墙。～屋。\n(3)等级地位低工资他比我～一级。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矮"},{"id":"glyph-kai-77f3","script":"kai","character":"石","reading":"shí；dàn","description":"shí：(1)构成地壳的矿物质硬块～破天惊（喻文章议论新奇惊人）。\n(2)指石刻金～。\n(3)指古代用来治病的针药～。药～之言（喻规劝别人的话）。\n(4)中国古代乐器八音之一。\n(5)姓。\ndàn：中国市制容量单位，十斗为一石。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-石"},{"id":"glyph-kai-77fe","script":"kai","character":"矾","reading":"fán","description":"铝的氧化物al2o3","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矾"},{"id":"glyph-kai-77ff","script":"kai","character":"矿","reading":"kuàng","description":"开采矿物的场所或单位\n石针,古代的一种医疗工具\n⒈蕴藏在地层中可供开采使用的自然资源铁～。煤～。金～。油～。气～。采～。\n⒉开采矿物的场所～山。～井。\n⒊特指矿石黄铁～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-矿"},{"id":"glyph-kai-7801","script":"kai","character":"码","reading":"mǎ","description":"表示数目的符号\n计算数目的用具\n指垒成的堆。相当于垛\n⒈代表数目的符号数～∨～儿。邮政编～。\n⒉计算数目的用具珐～。筹～子。\n⒊指一件事或一类的事两～事，不能混为一谈。\n⒋英美长度单位，1码等于0.9144米。\n⒌〈方〉垒起～雪人。那个小孩在～积木。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-码"},{"id":"glyph-kai-7802","script":"kai","character":"砂","reading":"shā","description":"shā：同沙”①②～粒。～纸。～轮。翻～（铸造器物的工作）。～糖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砂"},{"id":"glyph-kai-780c","script":"kai","character":"砌","reading":"qì；qiè","description":"qì：(1)建筑时垒砖石，用泥灰粘合～墙。堆～（亦喻写文章时使用大量华丽而无用的词语）。\n(2)台阶雕栏玉～。\nqiè：〔～末〕中国元曲中称戏曲舞台上所用的简单布景和特制的器物。亦作切末”（末”均读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砌"},{"id":"glyph-kai-780d","script":"kai","character":"砍","reading":"kǎn","description":"kǎn：(1)用刀斧等猛剁，用力劈～柴。～伐。\n(2)方言，把东西扔出去～砖头。\n(3)喻取缔（某组织）或取消（某项目、条款）原定的基建项目～了三分之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砍"},{"id":"glyph-kai-7814","script":"kai","character":"研","reading":"yán；yàn","description":"yán：(1)细磨（mó），碾～磨。～药。～墨。\n(2)深入地探求～究。钻～。～京练都（dū）（晋代左思作《三都赋》构思了十二年，后遂用研京练都”形容经年累月地构思文章）。\nyàn：古同砚”，砚台。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-研"},{"id":"glyph-kai-7816","script":"kai","character":"砖","reading":"zhuān","description":"像砖的东西\n⒈用土坯烧制的一种建筑材料瓷～。不用～块建房。\n⒉形状像砖的茶～。金～。冰～。\n砖tuán 1.揉捏，堆聚。\n砖chuán 1.陶制的纺锤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砖"},{"id":"glyph-kai-781a","script":"kai","character":"砚","reading":"yàn","description":"光滑的石头\n砚台\n制作砚\n⒈磨墨用的文具～台。\n⒉有同学关系的～兄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砚"},{"id":"glyph-kai-7830","script":"kai","character":"砰","reading":"pēng","description":"pēng：象声词，形容撞击或重物落地的声音～地一声，一块陨石坠落在地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砰"},{"id":"glyph-kai-7834","script":"kai","character":"破","reading":"pò","description":"pò：(1)碎，不完整碗打～。～灭。～旧。～败。～落。～陋。～颜（转为笑容）。～绽（衣服裂开，指事情或说话的漏洞或矛盾）。牢不可～。\n(2)分裂～裂。～读（同一个字形因意义不同而有两个以上读音，把习惯上通常的读音之外的读音，称破读”）。～土。\n(3)使损坏～坏。～损。\n(4)超出～例。～格。\n(5)花费，耗费～费。～财。～产。\n(6)打败，打垮～阵。～门。攻～。\n(7)揭穿～案。～译。～获。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-破"},{"id":"glyph-kai-7838","script":"kai","character":"砸","reading":"zá；zai","description":"zá：(1)打，捣～碎。～地基。～明火（方言，抢劫）。～饭碗（喻失业）。～锅（喻办事失败）。\n(2)打坏，打破碗～了。\n(3)失败戏演～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砸"},{"id":"glyph-kai-783e","script":"kai","character":"砾","reading":"lì","description":"砾石\n砾石屋面\n砾岩\n砾luò 1.见\"卓砾\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-砾"},{"id":"glyph-kai-7840","script":"kai","character":"础","reading":"chǔ","description":"事物的基底或根基","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-础"},{"id":"glyph-kai-7845","script":"kai","character":"硅","reading":"guī","description":"guī：一种非金属元素，是一种半导体材料，可用于制作半导体器件和集成电路。旧称矽”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-硅"},{"id":"glyph-kai-7855","script":"kai","character":"硕","reading":"shuò","description":"引申为大\n通石”。比喻坚固\n学识渊博、德高望重的\n又患无硕师名人与游,","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-硕"},{"id":"glyph-kai-785d","script":"kai","character":"硝","reading":"xiāo","description":"xiāo：(1)一些矿物盐的泛称～石。芒～。\n(2)用朴硝或芒硝加黄米面等处理毛皮，使皮板儿柔软～皮子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-硝"},{"id":"glyph-kai-786b","script":"kai","character":"硫","reading":"liú","description":"liú：一种非金属元素，普通称硫磺”或硫黄”，可用以制火药、火柴、杀虫剂等，亦可用来治皮肤病。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-硫"},{"id":"glyph-kai-786c","script":"kai","character":"硬","reading":"yìng","description":"yìng：(1)坚固，与软”相对坚～。～木。～煤。～卧。～席。～币。～笔（钢笔、铅笔、圆珠笔的统称）。～化。～件（计算机系统的组成部分，构成计算机的各个元件、部件和装置的统称）。～碰～（喻用强硬对付强硬，或强手对强手。）\n(2)刚强有力强～。～朗。～实。～气（ａ．刚强，有骨气；ｂ．有正当理由，于心无愧。气”读轻声）。～骨头。欺软怕～。\n(3)固执；勉强生～。～撑。～是。～顶。～挺。生拉～拽。\n(4)能力强，质量好～手。～功。过得～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-硬"},{"id":"glyph-kai-786e","script":"kai","character":"确","reading":"què","description":"坚定;坚决\n真实;符合事实\n通搉”。敲击\n乐亦不复\n⒋埆què\n⒈真实，实在～实。千真完～。～有其事。\n⒉肯定，坚定～认。～保不误。\n⒊土地瘠薄。\n⒋地不平。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-确"},{"id":"glyph-kai-788c","script":"kai","character":"碌","reading":"lù；liù","description":"lù：(1)平凡（指人）庸～。～～（如忙忙～～”）。\n(2)繁忙劳～。忙～。\nliù：〔～碡〕农具，用来轧脱谷粒或轧平场院。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碌"},{"id":"glyph-kai-788d","script":"kai","character":"碍","reading":"ài","description":"遮蔽;掩盖\n妨害，阻挡～事。阻～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碍"},{"id":"glyph-kai-788e","script":"kai","character":"碎","reading":"suì","description":"suì：(1)完整的东西破坏成零片或零块～裂。粉～。粉身～骨。\n(2)零星，不完整～屑。琐～。～琼。支离破～。\n(3)说话唠叨嘴～。闲言～语。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碎"},{"id":"glyph-kai-7891","script":"kai","character":"碑","reading":"bēi","description":"bēi：刻上文字纪念事业、功勋或作为标记的石头石～。丰～。墓～。口～。～文。～碣。～刻（刻在碑上的文字或图画）。～拓（tà）。～帖。～林。里程～（ａ．设于道路旁边用以记载里数的标志；ｂ．喻在历史发展进程中可以作为象征或标志的大事）。有口皆～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碑"},{"id":"glyph-kai-7897","script":"kai","character":"碗","reading":"wǎn","description":"wǎn：(1)盛（chéng）饮食的器皿，上面口大而圆饭～。茶～。盖～。～橱。\n(2)像碗的东西轴～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碗"},{"id":"glyph-kai-7898","script":"kai","character":"碘","reading":"diǎn","description":"diǎn：一种非金属元素，供制医药、染料等用。人体中缺少碘会引起甲状腺肿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碘"},{"id":"glyph-kai-789f","script":"kai","character":"碟","reading":"dié","description":"dié：盛食物等的器具，比盘子小，扁而浅～子。瓷～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碟"},{"id":"glyph-kai-78a7","script":"kai","character":"碧","reading":"bì","description":"bì：(1)青绿色的玉石～玉。\n(2)青绿色～绿。金～辉煌。～空。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碧"},{"id":"glyph-kai-78b0","script":"kai","character":"碰","reading":"pèng","description":"pèng：(1)撞击～击。～撞。～壁（喻事情办不成）。～～车。～钉子。\n(2)相遇～见。～头。～巧。\n(3)试探～运气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碰"},{"id":"glyph-kai-78b1","script":"kai","character":"碱","reading":"jiǎn","description":"jiǎn：(1)含在土里的一种物质，化学成分是碳酸钠，用做洗涤剂，亦用来中和发面中的酸味～土。～化。～荒。\n(2)化学上称能在水溶液中电离而生成氢氧离子（ＯＨ－）的化合物，如氢氧化钠等。溶液具有涩味，能使石蕊试纸变蓝，能跟酸中和而生成盐～金属。～式盐。～性岩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碱"},{"id":"glyph-kai-78b3","script":"kai","character":"碳","reading":"tàn","description":"tàn：一种非金属元素，无臭无味的固体。无定形碳有焦炭，木炭等，晶体碳有金刚石和石墨。冶铁和炼钢都需要焦碳。在工业上和医药上，碳和它的化合物用途极为广泛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碳"},{"id":"glyph-kai-78be","script":"kai","character":"碾","reading":"niǎn","description":"niǎn：(1)把东西轧碎或压平的器具～子。石～。汽～。\n(2)轧～米。～坊（亦作碾房”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-碾"},{"id":"glyph-kai-78c1","script":"kai","character":"磁","reading":"cí","description":"cí：(1)物质能吸引铁、镍等金属的性质～性。～力。～石。～极。～场。～化。～能。～感应。\n(2)同瓷”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-磁"},{"id":"glyph-kai-78c5","script":"kai","character":"磅","reading":"páng；bàng","description":"bàng：(1)英美制重量单位，一磅合0.45359237公斤。\n(2)用金属制成，底座上有承重金属板的台秤。\npáng：〔～礴〕ａ．广大无边，如气势～～”；ｂ．扩展，充满，如热情～～”。\n〔～音〕在证券、外汇等市场上，表示价格涨落的单位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-磅"},{"id":"glyph-kai-78ca","script":"kai","character":"磊","reading":"lěi","description":"lěi：石头多。\n〔～落（luò）〕心地光明坦白，如光明～～”，～～的胸怀”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-磊"},{"id":"glyph-kai-78d5","script":"kai","character":"磕","reading":"kē","description":"kē：(1)碰在硬东西上头～破了。～～碰碰（喻人和人之间发生的小冲突）。～头碰脑。～头（亦作叩头”）。\n(2)把东西向较硬处碰使附着物掉下来～打。～烟袋锅儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-磕"},{"id":"glyph-kai-78e8","script":"kai","character":"磨","reading":"mó；mò","description":"mó：(1)摩擦～刀。～墨。～练。～砺（摩擦使锐利，喻经受磨练）。～合。研～。～漆画。\n(2)阻碍，困难～难（nàn）∶事多～。\n(3)消耗，消灭～损。～耗。～灭。\n(4)拖延，耗时间～缠。～功夫。\nmò：(1)粉碎粮食的工具石～。电～。～盘。～坊（亦作磨房”）。推～。\n(2)用磨将粮食加工成所需的状态～面。～米。～豆腐。\n(3)掉转这个胡同太窄，～不过车来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-磨"},{"id":"glyph-kai-78f7","script":"kai","character":"磷","reading":"lín","description":"lín：一种非金属元素，常见的有白磷”和红磷”～火（俗称鬼火”）。～肥。～脂（含磷和氮的类脂质，是生物体的重要组成成分，动物的脑、肝、卵等含量较多）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-磷"},{"id":"glyph-kai-7901","script":"kai","character":"礁","reading":"jiāo","description":"jiāo：在海里或江里的岩石或珊瑚虫遗骸堆积成的岩状物～石。暗～。珊瑚～。触～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-礁"},{"id":"glyph-kai-793a","script":"kai","character":"示","reading":"shì","description":"shì：(1)表明，把事物拿出来或指出来使别人知道～警。～范。～弱。～威。～众。～意。告～。指～。请～。\n(2)对来信的敬称赐～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-示"},{"id":"glyph-kai-793c","script":"kai","character":"礼","reading":"lǐ","description":"⒈尊敬或客气的态度、动作～貌。敬～。\n⒉适应社会的道德观念和习俗形成的仪式、仪节典～。婚～。\n⒊〈表〉庆贺或敬意的事物～物。～品。国庆献～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-礼"},{"id":"glyph-kai-793e","script":"kai","character":"社","reading":"shè","description":"shè：(1)古代指土地神和祭祀土地神的地方、日子以及祭礼春～。秋～。～日。～稷（社”是土神，稷”是谷神，古代君主都祭社稷，后用以借指国家）。\n(2)团体或机构报～。结～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-社"},{"id":"glyph-kai-7940","script":"kai","character":"祀","reading":"sì","description":"sì：(1)祭祭～。～天。～祖。\n(2)中国殷代指年十有三～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祀"},{"id":"glyph-kai-7948","script":"kai","character":"祈","reading":"qí","description":"qí：(1)向神求福～祷。～福。～年。\n(2)请求～请。～求。～望。敬～照准。\n(3)．姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祈"},{"id":"glyph-kai-7956","script":"kai","character":"祖","reading":"zǔ","description":"zǔ：(1)父亲的上一辈～父。～考。～母。～妣。\n(2)称与祖父同辈的人外～父。外～母。\n(3)先代～宗。～业。～制。～祭。～国。\n(4)初，开始鼻～。\n(5)某种事业或派别的创始人～师。\n(6)出行时祭路神，引申为送行五月金陵西，～余白下亭”。～饯。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祖"},{"id":"glyph-kai-795d","script":"kai","character":"祝","reading":"zhù","description":"zhù：(1)表示对人对事的美好愿望～福。～寿。～捷。～辞。馨香祷～。\n(2)古代指男巫。\n(3)在神庙里管香火的人～融。庙～。\n(4)断～发（fà）（断发，后指僧尼削发出家）。\n(5)姓。\n(6)古同注”，敷涂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祝"},{"id":"glyph-kai-795e","script":"kai","character":"神","reading":"shén","description":"shén：(1)迷信的人称天地万物的创造者和所崇拜的人死后的精灵～仙。～怪。～主。～社。～农。～甫。～权。鬼使～差。\n(2)不可思议的，特别希奇的～秘。～奇。～异。～话。～机妙算。\n(3)不平凡的，特别高超的～勇。～医。～通。～圣。～速。\n(4)心思，心力，注意力劳～。凝～。～魂颠倒。\n(5)表情～色。～采。～姿。～志。\n(6)精神～清气爽。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-神"},{"id":"glyph-kai-795f","script":"kai","character":"祟","reading":"suì","description":"suì：迷信说法指鬼神给人带来的灾祸，借指不正当的行动作～。鬼鬼～～。邪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祟"},{"id":"glyph-kai-7960","script":"kai","character":"祠","reading":"cí","description":"cí：(1)封建制度下供奉祖宗、鬼神或有功德的人的房屋～堂。～庙。宗～。\n(2)古代指春祭（品物少，多文词）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祠"},{"id":"glyph-kai-7965","script":"kai","character":"祥","reading":"xiáng","description":"xiáng：(1)吉利～和。～瑞（吉祥的征兆）。不～。吉～。\n(2)吉凶的预兆～麟。～云。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祥"},{"id":"glyph-kai-7968","script":"kai","character":"票","reading":"piào；piāo","description":"piào：(1)纸币，通货钞～。～子。～额。\n(2)印的或写的凭证～据。～证。股～。车～。选～。\n(3)非职业演戏～戏。～友。\n(4)量词，相当于批”一～货物。\n(5)被匪绑架做抵押的人绑～儿。撕～儿。\npiāo：古同飘”，随风摆动飞扬。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-票"},{"id":"glyph-kai-796d","script":"kai","character":"祭","reading":"jì；zhài","description":"jì：(1)对死者表示追悼、敬意的仪式～奠。～礼。～灵。～典。～扫。\n(2)供奉鬼神或祖先～祖。～天。～祀。～灶。\n(3)使用（法宝）～起一件法宝。\nzhài：姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祭"},{"id":"glyph-kai-7977","script":"kai","character":"祷","reading":"dǎo","description":"祈祷,祈神求福\n①教徒或迷信的人向天、神求助～告。\n【祷告】宗教徒向天、神求保佑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祷"},{"id":"glyph-kai-7978","script":"kai","character":"祸","reading":"huò","description":"祸及枯骨。\n⒈灾害，苦难，跟\"福\"相对闯～了。出了车～。遭～殃。～兮福所倚，福兮～所伏。\n⒉损害，桅～害。～人之心。～国殃民。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-祸"},{"id":"glyph-kai-7980","script":"kai","character":"禀","reading":"bǐng","description":"bǐng：(1)承受，生成的～性。～赋。\n(2)指下对上报告～报。～复。回～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禀"},{"id":"glyph-kai-7981","script":"kai","character":"禁","reading":"jìn；jīn","description":"jīn：(1)受得住，耐久～受。～得住。～不起。弱不～风。\n(2)忍耐，制止不～笑起来。\njìn：(1)不许，制止～止。～绝。～书。～令。～赌。～欲。～锢。情不自～。\n(2)法律或习惯上制止的事犯～。违～品。\n(3)拘押囚～。监～。～闭。\n(4)古代称帝王的地方宫～。～苑。～卫。～军（古代指保卫京城或宫廷的军队）。\n(5)不能随便通行的地方～地。～区。\n(6)避忌～忌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禁"},{"id":"glyph-kai-7984","script":"kai","character":"禄","reading":"lù","description":"lù：(1)古代官吏的俸给～米。～位（借指官职）。～蠹（指追求官禄的人）。～食。俸～。无功受～。\n(2)福儿已薄～相，幸复得此妇”。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禄"},{"id":"glyph-kai-7985","script":"kai","character":"禅","reading":"chán","description":"表示与佛教有关的事物\n指禅房\n注除地于梁甫之阴,为墠\n①佛教用语。指静坐坐～。\n【禅定】〈宗〉佛教修行方法之一。安定而排除杂念的意思。禅定时，只能静坐，不能躺卧。认为如此能达到'明净'、'无我'的状态。俗称'坐禅'、'打坐'。\n【禅学】〈宗〉魏晋时期的佛学派别。偏重宗教修持，主要流行于北方◇也泛指佛学特别是禅宗一派。\n【禅宗】佛教的一派。以静坐默念为修行方法。据说南朝时菩提达摩来华传授禅法，经慧可、弘忍、惠能等的继承和发展，得以广泛流行。它以通俗易懂的修行方法取代其他宗\n派的繁琐理论，流行很广，唐宋时极盛。\n⒈梵文\"禅那\"的简称。意译为\"静思\"。佛教的一种修行法坐～。参～。又指有关佛教的～寺。～杖。\n⒈〈古〉帝王祭地的一种迷信礼仪。\n⒉禅让，指帝王让位给别人尧～位于舜。舜～位于禹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禅"},{"id":"glyph-kai-798f","script":"kai","character":"福","reading":"fú","description":"fú：(1)一切顺利，幸运，与祸”相对～气。享～。造～。祝～。～利。～音。～相。作威作～（原指统治者专行赏罚，独揽威权◇形容滥用权势，横行霸道）。\n(2)旧时妇女行礼的姿势万～。\n(3)祭神的酒肉～食。～酒。～物。\n(4)保祐小信未孚，神弗～也”。～荫。～佑。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-福"},{"id":"glyph-kai-79b9","script":"kai","character":"禹","reading":"yǔ","description":"yǔ：(1)传说中国夏代的第一个君主，他曾经治过洪水～域（指中国的疆域）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禹"},{"id":"glyph-kai-79bb","script":"kai","character":"离","reading":"lí","description":"长离,传说中的凤鸟,比喻有才华的人\n八卦之一,象征火\n⒈分开，分别～开。～别。～婚。～职。分～。\n⒉违背背～。\n⒊相距，隔开距～。隔～。我家～学校有一里路。\n⒋缺少生活～不了粮食。\n⒌八卦之一，代表火。\n离chī 1.古代传说中的一种龙。 2.猛兽。\n离gǔ 1.山名用字。\n离lì 1.丧失。 2.去掉;弃。\n离lǐ 1.见\"离跂\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-离"},{"id":"glyph-kai-79bd","script":"kai","character":"禽","reading":"qín","description":"qín：(1)鸟、兽的总称五～戏。\n(2)特指鸟类家～。飞～走兽。\n(3)古通擒”不～二毛。”\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禽"},{"id":"glyph-kai-79be","script":"kai","character":"禾","reading":"hé","description":"hé：(1)谷类植物的统称～苗。～本科（单子叶植物的一科）。\n(2)古代指粟（谷子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-禾"},{"id":"glyph-kai-79c0","script":"kai","character":"秀","reading":"xiù","description":"xiù：(1)植物吐穗开花，多指庄稼～穗。～而不实（喻人很聪明，却未做出实际成绩）。苗而不～（喻人早死或虚有其表）。\n(2)特别优异的，亦指特别优异的人～异。～才。优～◇起之～。\n(3)美丽而不俗气～丽。～劲。～俊。～拔（秀丽而挺拔）。清～。～外慧中（外貌俊美，内心聪明）。\n(4)中国元明两代称贵族、官僚、富室子弟（称平民子弟为郎”）不郎不～（喻不成材或没出息）。\n(5)茂盛佳木～而繁荫。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秀"},{"id":"glyph-kai-79c1","script":"kai","character":"私","reading":"sī","description":"sī：(1)个人的，自己的，与公”相对～人。～有。～见。～仇。～情。～营。～欲。\n(2)不公开的，秘密而又不合法的～自。～刑。～货。走～。～生子。\n(3)暗地里～议。～奔。隐～。窃窃～语。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-私"},{"id":"glyph-kai-79c3","script":"kai","character":"秃","reading":"tū","description":"tū：(1)人无头发，山无树木，树木无枝叶～子。～头。～顶。\n(2)鸟羽毛脱落，物体失去尖端～鹫。～笔。～针。\n(3)表示不圆满、不周全文章的开头写得有点～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秃"},{"id":"glyph-kai-79c6","script":"kai","character":"秆","reading":"gǎn","description":"gǎn：稻麦等植物的茎麦～儿。麻～儿。高粱～儿。烟～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秆"},{"id":"glyph-kai-79c9","script":"kai","character":"秉","reading":"bǐng","description":"bǐng：(1)拿着，持～烛。\n(2)掌握、主持～正。～公。\n(3)古代容量单位，一秉合六十斛。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秉"},{"id":"glyph-kai-79cb","script":"kai","character":"秋","reading":"qiū","description":"一年四季中的秋季，常与收获相联系。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-79cd","script":"kai","character":"种","reading":"zhǒng；zhòng；chóng","description":"zhǒng：物种、种类、种子。zhòng：播种、栽种。chóng：姓氏。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-79d1","script":"kai","character":"科","reading":"kē","description":"kē：(1)动植物的分类单位狮子属于猫～。槐树是豆～。\n(2)机关内部组织的划分～室。财务～。\n(3)学术或专业的类别～目。学～。文～。外～。\n(4)古代分科考选文武官吏后备人员的制度～举。～甲。～第。登～。\n(5)判定（刑罚）～处（chǔ）。～罚。\n(6)古典戏剧本中指示角色表演动作时的用语笑～。～白。\n(7)古同棵”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-科"},{"id":"glyph-kai-79d2","script":"kai","character":"秒","reading":"miǎo","description":"miǎo：(1)谷物种子壳上的芒，引申为细微，微小～忽（喻细微）。\n(2)时间的计算单位，一分钟的六十分之一～表。～针。\n(3)弧和角的计算单位，一分的六十分之一。\n(4)经纬度的计算单位，一分的六十分之一。\n(5)古代长度单位，一寸的万分之一。\n(6)古代容量单位，十撮为一秒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秒"},{"id":"glyph-kai-79d8","script":"kai","character":"秘","reading":"mì；bì","description":"mì：(1)不公开的，不让大家知道的～密。～藏（cáng）。～方。～诀。～计。～史。神～。奥～。\n(2)保守秘密～而不宣。\n(3)珍贵罕见～本。～籍。～宝。～府。\n(4)姓。\nbì：〔～鲁〕国名，在南美洲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秘"},{"id":"glyph-kai-79df","script":"kai","character":"租","reading":"zū","description":"zū：(1)出代价暂用别人的东西～房。～用。～借地。\n(2)收取一定的代价，把房屋、土地、器物等借给别人使用～佃。～价。～让。～赁（ａ．出租；ｂ．租用）。\n(3)出租所收取的钱或实物房～。地～。\n(4)田赋～税。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-租"},{"id":"glyph-kai-79e4","script":"kai","character":"秤","reading":"chèng","description":"chèng：衡量轻重的器具市～。磅～。～砣。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秤"},{"id":"glyph-kai-79e6","script":"kai","character":"秦","reading":"qín","description":"qín：(1)中国周代诸侯国名，在今陕西省和甘肃省一带朝（zhāo）～暮楚。～晋之好。～楼楚馆（旧时指妓院）。\n(2)中国朝代名～代。～镜高悬（喻法官判案的公正严明。亦称明镜高悬”）。\n(3)中国陕西省的别称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秦"},{"id":"glyph-kai-79e7","script":"kai","character":"秧","reading":"yāng","description":"yāng：(1)植物的幼苗～苗。树～儿。～田。育～。插～（特指稻苗）。\n(2)某些植物的茎瓜～。拉～。\n(3)某些初生的小动物鱼～子。\n(4)栽植；畜养～几棵树。他～了一池鱼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秧"},{"id":"glyph-kai-79e9","script":"kai","character":"秩","reading":"zhì","description":"zhì：(1)有条理，不混乱的情况～序。\n(2)古代官吏的俸禄官人益～，庶人益禄”。\n(3)古代官职级别委之常～。贬～三等。\n(4)十年七～寿辰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秩"},{"id":"glyph-kai-79ef","script":"kai","character":"积","reading":"jī","description":"累积;堆叠\n⒈堆积谷物农收～场。〈引〉堆积，聚集～肥。～少致巨。日～月累。～土而为山，～水而为海。\n⒊停滞～食。\n⒋算数乘法的得数乘～。\n①正面的，进步的～极因素。～极分子。\n②进取的，努力的～极争取。～极工作。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-积"},{"id":"glyph-kai-79f0","script":"kai","character":"称","reading":"chēng；chen","description":"符合,相当\n测定重量\n称 chèn合适；相当～心如意。又见chēng。\n【称体裁衣】按照身体的长短大小裁衣服。比喻做事要恰到好处。\n【称职】才能与职位相称；思想、能力等能胜任所担任的职务。\n①叫；叫做人们～他为老英雄。\n②名称昵～、蔑～。\n③说连声～好、点头～是。\n④赞扬～许。\n⑤测重量～2斤糖。\n⑥举～觞。又见chèn。\n【称道】称赞；夸奖值得～。\n【称孤道寡】以帝王、首脑自居。'孤'、'寡人'均为古代封建帝王的自称。现多讽刺自大的人。\n【称量瓶】精确称量分析试样用的小型玻璃仪器。一般为圆柱形，带有磨口密合的瓶盖。\n【称叹】赞叹～不已。\n【称谓】人们由于血缘和其他方面的相互关系以及由于身分、职业等等而得来的名称。如父亲、同志、先生、姑姑等。\n【称羡】称赞羡慕。\n【称雄】凭借武力或其他势力统治一方割据～。\n【称许】赞许。\n【称誉】表扬赞美。\n⒈衡量轻重～三斤肉。\n⒉名号名～。省～。别～。\n⒊叫，叫做～谓。～作。～兄道弟。\n⒋说，声言～谢。～好。～病。声～。\n⒌颂扬，赞许～颂。～许。～赞。\n⒍举，推举～兵。～贤举能。\n⒈适合，相当，相等～心。～职。相～。对～。德必～位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-称"},{"id":"glyph-kai-79f8","script":"kai","character":"秸","reading":"jiē","description":"jiē：农作物收割以后的茎麦～。豆～。秫～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秸"},{"id":"glyph-kai-79fb","script":"kai","character":"移","reading":"yí","description":"yí：(1)挪动～交。～植。～刻（过一段时间）。～晷（日影移动，犹言经过了一段时间）。～民。迁～。转～。～樽就教（端着酒去别人跟前以便求教，泛指主动前去向人请教）。\n(2)改变，变动～居。～易。～情（变易人的情志）。～动。潜～默化。\n(3)旧时公文的一种，行文不相统属的官署间～文。檄～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-移"},{"id":"glyph-kai-79fd","script":"kai","character":"秽","reading":"huì","description":"弄脏,弄污\n杂乱\n⒈荒芜田地荒～。\n⒉污浊，肮脏污～。〈喻〉丑陋，丑恶形～。淫～。邪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-秽"},{"id":"glyph-kai-7a00","script":"kai","character":"稀","reading":"xī","description":"xī：(1)事物中间距离远、空隙大，与密”相对，～疏。～落（luò）。～客。依～。\n(2)浓度小，含水分多的，与稠”相对～薄。～料。～释。\n(3)少～少。～罕。～奇。古～之年。\n(4)用在烂”、松”等形容词前面，表明程度深～烂。～碎。～松。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稀"},{"id":"glyph-kai-7a0b","script":"kai","character":"程","reading":"chéng","description":"chéng：(1)规矩，法式～式。～序。章～。规～。\n(2)进展，限度～度。进～。日～。过～。\n(3)道路的段落路～。行（xíng）～。里～。启～。前～。\n(4)衡量，考核计日～功。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-程"},{"id":"glyph-kai-7a0d","script":"kai","character":"稍","reading":"shāo；shào","description":"shāo：本义为禾末，引申为略微～～。～微。～许。～纵即逝。\nshào：〔～息〕军事或体操的口令。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稍"},{"id":"glyph-kai-7a0e","script":"kai","character":"税","reading":"shuì","description":"shuì：(1)国家向企业或集体、个人征收的货币或实物～收。～额。～款。～率。～法。～制。～务。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-税"},{"id":"glyph-kai-7a1a","script":"kai","character":"稚","reading":"zhì","description":"zhì：幼小幼～。～气。～子。～嫩。～弱。～拙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稚"},{"id":"glyph-kai-7a20","script":"kai","character":"稠","reading":"chóu","description":"chóu：(1)密，与稀”相对～密。～人广众。\n(2)浓～粥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稠"},{"id":"glyph-kai-7a33","script":"kai","character":"稳","reading":"wěn","description":"妥帖;稳妥\n⒈安定，固定，不动摇～定。～当。～如泰山。\n⒉妥贴～妥。\n⒊沉着，不轻浮～重。～健。\n⒋准确，有把握～操胜劵。～扎～打。\n⒌诱使他人暂缓行动你先～住他。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稳"},{"id":"glyph-kai-7a3b","script":"kai","character":"稻","reading":"dào","description":"dào：一年生草本植物，子实称稻谷”，去壳后称大米”。有水稻、旱稻之分。通常指水稻～子。～草。～米（亦称大米”）。～糠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稻"},{"id":"glyph-kai-7a3c","script":"kai","character":"稼","reading":"jià","description":"jià：(1)种植谷物，亦泛指农业劳动～穑。耕～。\n(2)谷物庄～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稼"},{"id":"glyph-kai-7a3d","script":"kai","character":"稽","reading":"jī；qǐ","description":"jī：(1)停留～留。～滞。\n(2)考核～核。～查。～考。无～之谈。\n(3)计较反唇相～。\n(4)至。\n(5)姓。\nqǐ：〔～首〕古代的一种礼节，跪下，拱手至地，头也至地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稽"},{"id":"glyph-kai-7a3f","script":"kai","character":"稿","reading":"gǎo","description":"gǎo：(1)谷类植物的茎秆～秆。～荐（稻草编的垫子）。\n(2)文字、图画的草底，又喻事先考虑的计划文～。～本。～件。讲～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-稿"},{"id":"glyph-kai-7a46","script":"kai","character":"穆","reading":"mù","description":"mù：(1)温和；～清（ａ．清平；ｂ．指上天）。～如清风。\n(2)恭敬严肃肃～。静～。\n(3)古同默”，沉默。\n(4)古代宗庙次序，父居右为昭”，子居左为穆”。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穆"},{"id":"glyph-kai-7a57","script":"kai","character":"穗","reading":"suì","description":"suì：(1)禾本植物聚生在茎的顶端的花和果实麦～。稻～。谷～。～轴。～状花序。\n(2)用丝线、布条或纸条等扎成的、挂起来往下垂的装饰品灯笼～儿。\n(3)中国广东省广州市的别称。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穗"},{"id":"glyph-kai-7a74","script":"kai","character":"穴","reading":"xué","description":"xué：(1)洞，窟窿孔～。石～。～居。～隙。龙潭虎～。\n(2)人体可以进行针灸的部位，多为神经末梢密集或较粗的神经干经过的地方～位。\n(3)旧艺人称在市场或广场上表演时所占的一块地方掌～的（指地主或班主）。走～。～头。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穴"},{"id":"glyph-kai-7a76","script":"kai","character":"究","reading":"jiū","description":"jiū：(1)推求，追查研～。推～。讲～。追～。深～。有案必～。\n(2)极，到底～竟（ａ．到底，如～～想干什么？”ｂ．结果，如大家都想知道个～～”）。终～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-究"},{"id":"glyph-kai-7a77","script":"kai","character":"穷","reading":"qióng","description":"⒈不得志，不显贵，跟\"达\"相对～不失义。\n⒉阻塞，不通，走投无路，跟\"通\"相对日暮途～。追～寇。\n⒊生活、处境困难～苦。～困。～则思变。\n⒋尽，完结理屈词～。无～无尽。\n⒌极端，彻底推究～凶极恶。～根究底。\n穷gōng 1.身体。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穷"},{"id":"glyph-kai-7a7a","script":"kai","character":"空","reading":"kōng；kòng；kǒng","description":"kōng：(1)不包含什么，没有内容～洞（ａ．没有内容的；ｂ．物体内部的窟窿）。～泛。～话。～旷。～乏。～～如也。～前绝后。凭～（无根据）。真～（没有任何东西）。\n(2)没有结果的，白白地～跑了一趟。～口无凭。\n(3)离开地面的，在地上面的地方～军。～气。～投。～运。\nkòng：(1)使空，腾出来～一个格。～出一间房来。\n(2)闲着，没被利用的～白。～地。～额。～房。～缺。\n(3)亏欠亏～。\nkǒng：古同孔”，洞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-空"},{"id":"glyph-kai-7a7f","script":"kai","character":"穿","reading":"chuān","description":"chuān：(1)破，透～透。揭～。～窬（钻洞和爬墙，指盗贼）。～凿。\n(2)通过，连通～过。～行（xíng）。\n(3)着（zhuó）衣服鞋袜～衣。～鞋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-穿"},{"id":"glyph-kai-7a81","script":"kai","character":"突","reading":"tū","description":"tū：(1)忽然～然。～现。～发。～变。～如其来。异军～起。～兀。\n(2)超出，冲破，猛冲～破。～围。～出。\n(3)烟囱曲～徙薪。灶～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-突"},{"id":"glyph-kai-7a83","script":"kai","character":"窃","reading":"qiè","description":"篡夺。指非其有而取之;不当受而受之\n⒈偷，用不合法、不正当的手段取得偷～。盗～犯。～据。～国大盗。\n⒉暗中，偷偷地～听。～取。～探。\n⒊私自，私下，旧时谦称自己～谓。～以为不妥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-窃"}];
